<script setup>
import { computed, ref } from 'vue';
import { settings, isOpen } from '../store';
import { api, errorMessage } from '../api';
const props=defineProps({page:{type:String,default:'about'}});
const form=ref({name:'',email:'',message:''});const busy=ref(false);const error=ref('');const sent=ref(false);
const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
async function send(){busy.value=true;error.value='';try{await api.post('/contact',form.value);sent.value=true;form.value={name:'',email:'',message:''};}catch(failure){error.value=errorMessage(failure);}finally{busy.value=false;}}
</script>
<template><section class="container section-space info-page"><template v-if="page==='about'"><div class="page-heading"><div class="eyebrow">MORE THAN A MEAL</div><h1>Your everyday place.<br>With a little <span class="serif accent">extra.</span></h1></div><div class="info-grid"><div class="panel"><h2>Welcome to {{ settings.name }}.</h2><p>We believe the best meals bring people together. That’s why we put care into every ingredient, every dish, and every welcome.</p><p>From flame-grilled burgers to comforting classics, our food is made to order. Pull up a chair, share a feast, or bring a little flavor home.</p><router-link to="/menu" class="button">Find your favorite ↗</router-link></div><div class="panel"><h3>A little fire. A lot of care.</h3><ul class="feature-list"><li>Fresh ingredients, prepared to order</li><li>Sizes and extras to make it yours</li><li>Delivery to supported areas</li><li>Easy pickup and cash payments</li></ul><router-link to="/contact" class="text-button">Come say hello →</router-link></div></div></template><template v-else-if="page==='contact'"><div class="page-heading"><div class="eyebrow">COME HUNGRY. STAY A WHILE.</div><h1>Let’s <span class="serif accent">connect.</span></h1><p>{{ isOpen ? 'We’re open for orders.' : 'We’re currently closed for orders.' }}</p></div><div class="info-grid"><div class="panel"><h2>Visit {{ settings.name }}</h2><p>{{ settings.address || 'Our location details are being updated.' }}</p><p v-if="settings.phone"><a :href="`tel:${settings.phone}`">{{ settings.phone }}</a></p><p v-if="settings.email"><a :href="`mailto:${settings.email}`">{{ settings.email }}</a></p><h3 class="history-heading">Opening hours</h3><div v-for="(hours,index) in settings.opening_hours" :key="index" class="hours-row"><span>{{ days[index] }}</span><strong>{{ hours.enabled ? (hours.open===hours.close ? 'Open 24 hours' : `${hours.open} – ${hours.close}`) : 'Closed' }}</strong></div><p class="small-note">Times are shown in {{ settings.timezone }}. A closing time earlier than opening means the following morning.</p></div><div class="panel"><h2>Say hello.</h2><p>Questions about your order? Tell us how we can help.</p><div v-if="error" class="form-error" role="alert">{{ error }}</div><div v-if="sent" class="form-success" role="status">Your message has been sent to the restaurant.</div><form @submit.prevent="send" class="form-grid"><label class="full-width">Name<input v-model="form.name" required maxlength="80" autocomplete="name"></label><label class="full-width">Email<input v-model="form.email" type="email" required autocomplete="email"></label><label class="full-width">Your message<textarea v-model="form.message" required minlength="10" maxlength="3000"></textarea></label><button class="button" :disabled="busy">{{ busy ? 'Sending…' : 'Send message' }} ↗</button></form></div></div></template><template v-else><div class="page-heading"><div class="eyebrow">THE DETAILS</div><h1>{{ page==='privacy' ? 'Your privacy.' : 'Ordering terms.' }}</h1></div><div class="panel legal-copy"><template v-if="page==='privacy'"><h3>Information used for your order</h3><p>We store your account details, saved addresses, order history, and messages so the restaurant can prepare and fulfill your orders. Passwords are hashed. Your cart is saved on your device and, when signed in, in your account.</p><h3>Payments and contact</h3><p>Cash orders do not collect card or bank details. Order updates may be sent to the email address you provide. Contact the restaurant to ask about your information or request its removal, subject to necessary order records.</p><h3>Cookies and images</h3><p>Session cookies keep you signed in and protect your requests. Menu images may load from an external image service.</p></template><template v-else><h3>Ordering and availability</h3><p>Orders are subject to restaurant confirmation, menu availability, opening hours, supported delivery areas, and minimum delivery amounts. The final total, including applicable tax and delivery charges, is shown before you confirm.</p><h3>Payment and changes</h3><p>Pay in cash on delivery or pickup. To change or cancel an order, contact the restaurant promptly. Preparation and delivery times are estimates.</p><h3>Allergies and reservations</h3><p>Include allergy information in your order notes and contact the restaurant before ordering. Reservation requests remain pending until restaurant staff confirm availability.</p></template><p class="small-note">These are starter policy texts. The restaurant should review them before public launch.</p></div></template></section></template>
